code_example:
#include <iostream>

class ErrorCondition {
public:
    explicit ErrorCondition(int code) : code_(code) {}
    void display() const { std::cout << "Error code: " << code_ << std::endl; }
private:
    int code_;
};

class ErrorHandler {
public:
    virtual ~ErrorHandler() = default;
    virtual ErrorCondition default_error_condition(int ev) const noexcept {
        return ErrorCondition(ev);
    }
};

class CustomErrorHandler : public ErrorHandler {
public:
    ErrorCondition default_error_condition(int ev) const noexcept override {
        // Custom logic for error condition
        return ErrorCondition(ev + 100);
    }
};

int main() {
    ErrorHandler* handler = new CustomErrorHandler();
    ErrorCondition ec = handler->default_error_condition(42);
    ec.display();
    delete handler;
    return 0;
}
